// Confere o pedido contra o contrato insight-v1 (docker/n8n/contrato/ida.schema.json).
const p = ($json.body !== undefined ? $json.body : $json) || {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const PRISMAS = ['seguranca_psicologica', 'lideranca_adaptativa', 'cultura_empreendedora', 'adaptabilidade_cognitiva', 'neuroinovacao_prisma'];
const DIMENSOES = ['S2', 'S4', 'S5A', 'S5B', 'S6', 'S7', 'S8'];
const IDIOMAS = ['pt-BR', 'en', 'es'];
const SETORES = ['Marketing', 'Financeiro', 'Administrativo', 'RecursosHumanos', 'TecnologiaInformacao'];
const NIVEIS = ['alinhado', 'moderado', 'dividido'];

const idOk = typeof p.insight_id === 'string' && UUID.test(p.insight_id);
const tentativaOk = Number.isInteger(p.attempt) && p.attempt >= 1;
if (!idOk || !tentativaOk) {
  // Sem id ou tentativa, não há para quem devolver: fica só no log desta execução.
  return { json: { acao: 'descartar', motivo: 'sem insight_id ou attempt utilizável' } };
}

const recusar = function (erro) {
  return {
    json: {
      acao: 'recusar',
      motivo: erro,
      volta: { contract_version: 'insight-v1', insight_id: p.insight_id, attempt: p.attempt, status: 'failed', error: erro, retryable: false }
    }
  };
};

const objeto = function (o) { return o !== null && typeof o === 'object' && !Array.isArray(o); };
const nota = function (n) { return typeof n === 'number' && n >= 0 && n <= 100; };
const inteiro = function (n, min) { return Number.isInteger(n) && n >= min; };
const mesmasChaves = function (obj, chaves) {
  return objeto(obj) && Object.keys(obj).sort().join(',') === chaves.slice().sort().join(',');
};
const notasOk = function (obj, chaves) {
  return mesmasChaves(obj, chaves) && chaves.every(function (k) { return nota(obj[k]); });
};
const r = p.result || {};
const resultadoOk =
  notasOk(r.prismas, PRISMAS) &&
  notasOk(r.dimensions, DIMENSOES) &&
  PRISMAS.indexOf(r.destaque) >= 0 &&
  PRISMAS.indexOf(r.oportunidade) >= 0;

const baseOk =
  p.contract_version === 'insight-v1' &&
  (p.scope === 'individual' || p.scope === 'organization') &&
  IDIOMAS.indexOf(p.language) >= 0 &&
  resultadoOk;
if (!baseOk) {
  return recusar('invalid_payload');
}

if (p.scope === 'organization') {
  // Pedido da empresa (task 15): agregado do período, sem resposta aberta (P-090).
  const per = p.period;
  const periodoOk = objeto(per) && typeof per.opens_at === 'string' &&
    (per.closes_at === null || typeof per.closes_at === 'string');
  const part = p.participation;
  const participacaoOk = objeto(part) && inteiro(part.submitted, 1) && inteiro(part.invited, 1);
  const setoresOk = Array.isArray(p.departments) && p.departments.every(function (s) {
    return objeto(s) && SETORES.indexOf(s.department) >= 0 && inteiro(s.submitted, 1) && notasOk(s.prismas, PRISMAS);
  });
  const alinhamentoOk = mesmasChaves(p.alignment, PRISMAS) && PRISMAS.every(function (k) {
    const a = p.alignment[k];
    return objeto(a) && NIVEIS.indexOf(a.level) >= 0 && mesmasChaves(a.bands, ['baixa', 'media', 'alta']) &&
      inteiro(a.bands.baixa, 0) && inteiro(a.bands.media, 0) && inteiro(a.bands.alta, 0);
  });
  if (!periodoOk || !participacaoOk || !setoresOk || !alinhamentoOk || p.open_answers !== undefined) {
    return recusar('invalid_payload');
  }
  return { json: { acao: 'gerar', pedido: p } };
}

const texto = function (t) { return typeof t === 'string' && t.trim().length > 0; };
const abertasOk = Array.isArray(p.open_answers) && p.open_answers.every(function (a) {
  return a && texto(a.section) && texto(a.question) && texto(a.answer);
});
if (!abertasOk) {
  return recusar('invalid_payload');
}

return { json: { acao: 'gerar', pedido: p } };
